class Template:
    """Class to hold a template and manage caching and rendering."""

    def __init__(self, template, hass=None):
        """Instantiate a template."""
        if not isinstance(template, str):
            raise TypeError('Expected template to be a string')
        self.template = template
        self._compiled_code = None
        self._compiled = None
        self.hass = hass

    def ensure_valid(self):
        """Return if template is valid."""
        if self._compiled_code is not None:
            return
        try:
            self._compiled_code = ENV.compile(self.template)
        except jinja2.exceptions.TemplateSyntaxError as err:
            raise TemplateError(err)

    def extract_entities(self, variables=None):
        """Extract all entities for state_changed listener."""
        return extract_entities(self.template, variables)

    def render(self, variables: TemplateVarsType=None, **kwargs):
        """Render given template."""
        if variables is not None:
            kwargs.update(variables)
        return run_callback_threadsafe(self.hass.loop, self.async_render,
            kwargs).result()

    def async_render(self, variables: TemplateVarsType=None, **kwargs) ->str:
        """Render given template.

        This method must be run in the event loop.
        """
        if self._compiled is None:
            self._ensure_compiled()
        if variables is not None:
            kwargs.update(variables)
        try:
            return self._compiled.render(kwargs).strip()
        except jinja2.TemplateError as err:
            raise TemplateError(err)

    def render_with_possible_json_value(self, value, error_value=_SENTINEL):
        """Render template with value exposed.

        If valid JSON will expose value_json too.
        """
        return run_callback_threadsafe(self.hass.loop, self.
            async_render_with_possible_json_value, value, error_value).result()

    def async_render_with_possible_json_value(self, value, error_value=
        _SENTINEL, variables=None):
        """Render template with value exposed.

        If valid JSON will expose value_json too.

        This method must be run in the event loop.
        """
        if self._compiled is None:
            self._ensure_compiled()
        variables = dict(variables or {})
        variables['value'] = value
        try:
            variables['value_json'] = json.loads(value)
        except ValueError:
            pass
        try:
            return self._compiled.render(variables).strip()
        except jinja2.TemplateError as ex:
            if error_value is _SENTINEL:
                _LOGGER.error(
                    'Error parsing value: %s (value: %s, template: %s)', ex,
                    value, self.template)
            return value if error_value is _SENTINEL else error_value

    def _ensure_compiled(self):
        """Bind a template to a specific hass instance."""
        self.ensure_valid()
        assert self.hass is not None, 'hass variable not set on template'
        template_methods = TemplateMethods(self.hass)
        global_vars = ENV.make_globals({'closest': template_methods.closest,
            'distance': template_methods.distance, 'is_state': self.hass.
            states.is_state, 'is_state_attr': template_methods.
            is_state_attr, 'state_attr': template_methods.state_attr,
            'states': AllStates(self.hass)})
        self._compiled = jinja2.Template.from_code(ENV, self._compiled_code,
            global_vars, None)
        return self._compiled

    def __eq__(self, other):
        """Compare template with another."""
        return (self.__class__ == other.__class__ and self.template ==
            other.template and self.hass == other.hass)

