class HTMLFormatter(TableFormatter):
    indent_delta = 2

    def __init__(self, formatter, classes=None, notebook=False, border=None,
        table_id=None, render_links=False):
        self.fmt = formatter
        self.classes = classes
        self.frame = self.fmt.frame
        self.columns = self.fmt.tr_frame.columns
        self.elements = []
        self.bold_rows = self.fmt.kwds.get('bold_rows', False)
        self.escape = self.fmt.kwds.get('escape', True)
        self.show_dimensions = self.fmt.show_dimensions
        self.notebook = notebook
        if border is None:
            border = get_option('display.html.border')
        self.border = border
        self.table_id = table_id
        self.render_links = render_links

    @property
    def show_row_idx_names(self):
        return all((self.fmt.has_index_names, self.fmt.index, self.fmt.
            show_index_names))

    @property
    def show_col_idx_names(self):
        return all((self.fmt.has_column_names, self.fmt.show_index_names,
            self.fmt.header))

    @property
    def row_levels(self):
        if self.fmt.index:
            return self.frame.index.nlevels
        elif self.show_col_idx_names:
            return 1
        return 0

    @property
    def is_truncated(self):
        return self.fmt.is_truncated

    @property
    def ncols(self):
        return len(self.fmt.tr_frame.columns)

    def write(self, s, indent=0):
        rs = pprint_thing(s)
        self.elements.append(' ' * indent + rs)

    def write_th(self, s, indent=0, tags=None):
        if self.fmt.col_space is not None and self.fmt.col_space > 0:
            tags = tags or ''
            tags += 'style="min-width: {colspace};"'.format(colspace=self.
                fmt.col_space)
        return self._write_cell(s, kind='th', indent=indent, tags=tags)

    def write_td(self, s, indent=0, tags=None):
        return self._write_cell(s, kind='td', indent=indent, tags=tags)

    def _write_cell(self, s, kind='td', indent=0, tags=None):
        if tags is not None:
            start_tag = '<{kind} {tags}>'.format(kind=kind, tags=tags)
        else:
            start_tag = '<{kind}>'.format(kind=kind)
        if self.escape:
            esc = OrderedDict([('&', '&amp;'), ('<', '&lt;'), ('>', '&gt;')])
        else:
            esc = {}
        rs = pprint_thing(s, escape_chars=esc).strip()
        if self.render_links and _is_url(rs):
            rs_unescaped = pprint_thing(s, escape_chars={}).strip()
            start_tag += '<a href="{url}" target="_blank">'.format(url=
                rs_unescaped)
            end_a = '</a>'
        else:
            end_a = ''
        self.write(u'{start}{rs}{end_a}</{kind}>'.format(start=start_tag,
            rs=rs, end_a=end_a, kind=kind), indent)

    def write_tr(self, line, indent=0, indent_delta=0, header=False, align=
        None, tags=None, nindex_levels=0):
        if tags is None:
            tags = {}
        if align is None:
            self.write('<tr>', indent)
        else:
            self.write('<tr style="text-align: {align};">'.format(align=
                align), indent)
        indent += indent_delta
        for i, s in enumerate(line):
            val_tag = tags.get(i, None)
            if header or self.bold_rows and i < nindex_levels:
                self.write_th(s, indent, tags=val_tag)
            else:
                self.write_td(s, indent, tags=val_tag)
        indent -= indent_delta
        self.write('</tr>', indent)

    def write_style(self):
        template_first = '            <style scoped>'
        template_last = '            </style>'
        template_select = """                .dataframe %s {
                    %s: %s;
                }"""
        element_props = [('tbody tr th:only-of-type', 'vertical-align',
            'middle'), ('tbody tr th', 'vertical-align', 'top')]
        if isinstance(self.columns, ABCMultiIndex):
            element_props.append(('thead tr th', 'text-align', 'left'))
            if self.show_row_idx_names:
                element_props.append(('thead tr:last-of-type th',
                    'text-align', 'right'))
        else:
            element_props.append(('thead th', 'text-align', 'right'))
        template_mid = '\n\n'.join(map(lambda t: template_select % t,
            element_props))
        template = dedent('\n'.join((template_first, template_mid,
            template_last)))
        if self.notebook:
            self.write(template)

    def write_result(self, buf):
        indent = 0
        id_section = ''
        frame = self.frame
        _classes = ['dataframe']
        use_mathjax = get_option('display.html.use_mathjax')
        if not use_mathjax:
            _classes.append('tex2jax_ignore')
        if self.classes is not None:
            if isinstance(self.classes, str):
                self.classes = self.classes.split()
            if not isinstance(self.classes, (list, tuple)):
                raise AssertionError('classes must be list or tuple, not {typ}'
                    .format(typ=type(self.classes)))
            _classes.extend(self.classes)
        if self.notebook:
            self.write('<div>')
        self.write_style()
        if self.table_id is not None:
            id_section = ' id="{table_id}"'.format(table_id=self.table_id)
        self.write('<table border="{border}" class="{cls}"{id_section}>'.
            format(border=self.border, cls=' '.join(_classes), id_section=
            id_section), indent)
        indent += self.indent_delta
        indent = self._write_header(indent)
        indent = self._write_body(indent)
        self.write('</table>', indent)
        if self.should_show_dimensions:
            by = chr(215) if compat.PY3 else unichr(215)
            self.write(u('<p>{rows} rows {by} {cols} columns</p>').format(
                rows=len(frame), by=by, cols=len(frame.columns)))
        if self.notebook:
            self.write('</div>')
        buffer_put_lines(buf, self.elements)

    def _write_col_header(self, indent):
        truncate_h = self.fmt.truncate_h
        if isinstance(self.columns, ABCMultiIndex):
            template = 'colspan="{span:d}" halign="left"'
            if self.fmt.sparsify:
                sentinel = com.sentinel_factory()
            else:
                sentinel = None
            levels = self.columns.format(sparsify=sentinel, adjoin=False,
                names=False)
            level_lengths = get_level_lengths(levels, sentinel)
            inner_lvl = len(level_lengths) - 1
            for lnum, (records, values) in enumerate(zip(level_lengths, levels)
                ):
                if truncate_h:
                    ins_col = self.fmt.tr_col_num
                    if self.fmt.sparsify:
                        recs_new = {}
                        for tag, span in list(records.items()):
                            if tag >= ins_col:
                                recs_new[tag + 1] = span
                            elif tag + span > ins_col:
                                recs_new[tag] = span + 1
                                if lnum == inner_lvl:
                                    values = values[:ins_col] + (u('...'),
                                        ) + values[ins_col:]
                                else:
                                    values = values[:ins_col] + (values[
                                        ins_col - 1],) + values[ins_col:]
                            else:
                                recs_new[tag] = span
                            if tag + span == ins_col:
                                recs_new[ins_col] = 1
                                values = values[:ins_col] + (u('...'),
                                    ) + values[ins_col:]
                        records = recs_new
                        inner_lvl = len(level_lengths) - 1
                        if lnum == inner_lvl:
                            records[ins_col] = 1
                    else:
                        recs_new = {}
                        for tag, span in list(records.items()):
                            if tag >= ins_col:
                                recs_new[tag + 1] = span
                            else:
                                recs_new[tag] = span
                        recs_new[ins_col] = 1
                        records = recs_new
                        values = values[:ins_col] + [u('...')] + values[ins_col
                            :]
                row = [''] * (self.row_levels - 1)
                if self.fmt.index or self.show_col_idx_names:
                    if self.fmt.show_index_names:
                        name = self.columns.names[lnum]
                        row.append(pprint_thing(name or ''))
                    else:
                        row.append('')
                tags = {}
                j = len(row)
                for i, v in enumerate(values):
                    if i in records:
                        if records[i] > 1:
                            tags[j] = template.format(span=records[i])
                    else:
                        continue
                    j += 1
                    row.append(v)
                self.write_tr(row, indent, self.indent_delta, tags=tags,
                    header=True)
        else:
            row = [''] * (self.row_levels - 1)
            if self.fmt.index or self.show_col_idx_names:
                if self.fmt.show_index_names:
                    row.append(self.columns.name or '')
                else:
                    row.append('')
            row.extend(self.columns)
            align = self.fmt.justify
            if truncate_h:
                ins_col = self.row_levels + self.fmt.tr_col_num
                row.insert(ins_col, '...')
            self.write_tr(row, indent, self.indent_delta, header=True,
                align=align)

    def _write_row_header(self, indent):
        truncate_h = self.fmt.truncate_h
        row = [(x if x is not None else '') for x in self.frame.index.names
            ] + [''] * (self.ncols + (1 if truncate_h else 0))
        self.write_tr(row, indent, self.indent_delta, header=True)

    def _write_header(self, indent):
        if not (self.fmt.header or self.show_row_idx_names):
            return indent
        self.write('<thead>', indent)
        indent += self.indent_delta
        if self.fmt.header:
            self._write_col_header(indent)
        if self.show_row_idx_names:
            self._write_row_header(indent)
        indent -= self.indent_delta
        self.write('</thead>', indent)
        return indent

    def _write_body(self, indent):
        self.write('<tbody>', indent)
        indent += self.indent_delta
        fmt_values = {i: self.fmt._format_col(i) for i in range(self.ncols)}
        if self.fmt.index and isinstance(self.frame.index, ABCMultiIndex):
            self._write_hierarchical_rows(fmt_values, indent)
        else:
            self._write_regular_rows(fmt_values, indent)
        indent -= self.indent_delta
        self.write('</tbody>', indent)
        indent -= self.indent_delta
        return indent

    def _write_regular_rows(self, fmt_values, indent):
        truncate_h = self.fmt.truncate_h
        truncate_v = self.fmt.truncate_v
        nrows = len(self.fmt.tr_frame)
        if self.fmt.index:
            fmt = self.fmt._get_formatter('__index__')
            if fmt is not None:
                index_values = self.fmt.tr_frame.index.map(fmt)
            else:
                index_values = self.fmt.tr_frame.index.format()
        row = []
        for i in range(nrows):
            if truncate_v and i == self.fmt.tr_row_num:
                str_sep_row = ['...'] * len(row)
                self.write_tr(str_sep_row, indent, self.indent_delta, tags=
                    None, nindex_levels=self.row_levels)
            row = []
            if self.fmt.index:
                row.append(index_values[i])
            elif self.show_col_idx_names:
                row.append('')
            row.extend(fmt_values[j][i] for j in range(self.ncols))
