                        index=new_index, name=self.obj.name)._data
                    self.obj._maybe_update_cacher(clear=True)
                    return self.obj
                elif self.ndim == 2:
                    if not len(self.obj.columns):
                        raise ValueError(
                            'cannot set a frame with no defined columns')
                    if isinstance(value, Series):
                        value = value.reindex(index=self.obj.columns, copy=True
                            )
                        value.name = indexer
                    else:
                        if is_list_like_indexer(value):
                            if len(value) != len(self.obj.columns):
                                raise ValueError(
                                    'cannot set a row with mismatched columns')
                        value = Series(value, index=self.obj.columns, name=
                            indexer)
                    self.obj._data = self.obj.append(value)._data
                    self.obj._maybe_update_cacher(clear=True)
                    return self.obj
                elif self.ndim >= 3:
                    return self.obj.__setitem__(indexer, value)
        item_labels = self.obj._get_axis(info_axis)
        if take_split_path:
            if not isinstance(indexer, tuple):
                indexer = self._tuplify(indexer)
            if isinstance(value, ABCSeries):
                value = self._align_series(indexer, value)
            info_idx = indexer[info_axis]
            if is_integer(info_idx):
                info_idx = [info_idx]
            labels = item_labels[info_idx]
            if len(labels) == 1 and isinstance(self.obj[labels[0]].axes[0],
                MultiIndex):
                item = labels[0]
                obj = self.obj[item]
                index = obj.index
                idx = indexer[:info_axis][0]
                plane_indexer = tuple([idx]) + indexer[info_axis + 1:]
                lplane_indexer = length_of_indexer(plane_indexer[0], index)
                if is_list_like_indexer(value) and np.iterable(value
                    ) and lplane_indexer != len(value):
                    if len(obj[idx]) != len(value):
                        raise ValueError(
                            'cannot set using a multi-index selection indexer with a different length than the value'
                            )
                    value = getattr(value, 'values', value).ravel()
                    idx = index._convert_slice_indexer(idx)
                    obj._consolidate_inplace()
                    obj = obj.copy()
                    obj._data = obj._data.setitem(indexer=tuple([idx]),
                        value=value)
                    self.obj[item] = obj
                    return
            else:
                plane_indexer = indexer[:info_axis] + indexer[info_axis + 1:]
                if info_axis > 0:
                    plane_axis = self.obj.axes[:info_axis][0]
                    lplane_indexer = length_of_indexer(plane_indexer[0],
                        plane_axis)
                else:
                    lplane_indexer = 0

            def setter(item, v):
                s = self.obj[item]
                pi = plane_indexer[0] if lplane_indexer == 1 else plane_indexer
                if isinstance(pi, tuple) and all(com.is_null_slice(idx) or
                    com.is_full_slice(idx, len(self.obj)) for idx in pi):
                    s = v
                else:
                    s._consolidate_inplace()
                    s = s.copy()
                    s._data = s._data.setitem(indexer=pi, value=v)
                    s._maybe_update_cacher(clear=True)
                self.obj[item] = s

            def can_do_equal_len():
                """ return True if we have an equal len settable """
                if not len(labels) == 1 or not np.iterable(value) or is_scalar(
                    plane_indexer[0]):
                    return False
                item = labels[0]
                index = self.obj[item].index
                values_len = len(value)
                if len(index) == values_len:
                    return True
                elif lplane_indexer == values_len:
                    return True
                return False
            if is_list_like_indexer(value) and getattr(value, 'ndim', 1) > 0:
                if isinstance(value, ABCDataFrame) and value.ndim > 1:
                    sub_indexer = list(indexer)
                    multiindex_indexer = isinstance(labels, MultiIndex)
                    for item in labels:
                        if item in value:
                            sub_indexer[info_axis] = item
                            v = self._align_series(tuple(sub_indexer),
                                value[item], multiindex_indexer)
                        else:
                            v = np.nan
                        setter(item, v)
                elif hasattr(value, 'ndim') and value.ndim == 2 or (not
                    hasattr(value, 'ndim') and np.array(value).ndim) == 2:
                    value = np.array(value, dtype=object)
                    if len(labels) != value.shape[1]:
                        raise ValueError(
                            'Must have equal len keys and value when setting with an ndarray'
                            )
                    for i, item in enumerate(labels):
                        setter(item, value[:, i].tolist())
                elif can_do_equal_len():
                    setter(labels[0], value)
                else:
                    if len(labels) != len(value):
                        raise ValueError(
                            'Must have equal len keys and value when setting with an iterable'
                            )
                    for item, v in zip(labels, value):
                        setter(item, v)
            else:
                for item in labels:
                    setter(item, value)
        else:
            if isinstance(indexer, tuple):
                indexer = maybe_convert_ix(*indexer)
                if len(indexer) > info_axis and is_integer(indexer[info_axis]
                    ) and all(com.is_null_slice(idx) for i, idx in
                    enumerate(indexer) if i != info_axis
                    ) and item_labels.is_unique:
                    self.obj[item_labels[indexer[info_axis]]] = value
                    return
            if isinstance(value, (ABCSeries, dict)):
                value = self._align_series(indexer, Series(value))
            elif isinstance(value, ABCDataFrame):
                value = self._align_frame(indexer, value)
            if isinstance(value, ABCPanel):
                value = self._align_panel(indexer, value)
            self.obj._check_is_chained_assignment_possible()
            self.obj._consolidate_inplace()
            self.obj._data = self.obj._data.setitem(indexer=indexer, value=
                value)
            self.obj._maybe_update_cacher(clear=True)

    def _align_series(self, indexer, ser, multiindex_indexer=False):
        """
        Parameters
        ----------
        indexer : tuple, slice, scalar
            The indexer used to get the locations that will be set to
            `ser`

        ser : pd.Series
            The values to assign to the locations specified by `indexer`

        multiindex_indexer : boolean, optional
            Defaults to False. Should be set to True if `indexer` was from
            a `pd.MultiIndex`, to avoid unnecessary broadcasting.


        Returns:
        --------
        `np.array` of `ser` broadcast to the appropriate shape for assignment
        to the locations selected by `indexer`

        """
        if isinstance(indexer, (slice, np.ndarray, list, Index)):
            indexer = tuple([indexer])
        if isinstance(indexer, tuple):

            def ravel(i):
                return i.ravel() if isinstance(i, np.ndarray) else i
            indexer = tuple(map(ravel, indexer))
            aligners = [(not com.is_null_slice(idx)) for idx in indexer]
            sum_aligners = sum(aligners)
            single_aligner = sum_aligners == 1
            is_frame = self.obj.ndim == 2
            is_panel = self.obj.ndim >= 3
            obj = self.obj
            if is_frame:
                single_aligner = single_aligner and aligners[0]
            elif is_panel:
                single_aligner = single_aligner and (aligners[1] or aligners[2]
                    )
            if sum_aligners == self.ndim and all(is_sequence(_) for _ in
                indexer):
                ser = ser.reindex(obj.axes[0][indexer[0]], copy=True)._values
                if len(indexer) > 1 and not multiindex_indexer:
                    len_indexer = len(indexer[1])
                    ser = np.tile(ser, len_indexer).reshape(len_indexer, -1).T
                return ser
            for i, idx in enumerate(indexer):
                ax = obj.axes[i]
                if is_sequence(idx) or isinstance(idx, slice):
                    if single_aligner and com.is_null_slice(idx):
                        continue
                    new_ix = ax[idx]
                    if not is_list_like_indexer(new_ix):
                        new_ix = Index([new_ix])
                    else:
                        new_ix = Index(new_ix)
                    if ser.index.equals(new_ix) or not len(new_ix):
                        return ser._values.copy()
                    return ser.reindex(new_ix)._values
                elif single_aligner and is_frame:
                    ax = self.obj.axes[1]
                    if ser.index.equals(ax) or not len(ax):
                        return ser._values.copy()
                    return ser.reindex(ax)._values
                elif single_aligner:
                    broadcast = []
                    for n, labels in enumerate(self.obj._get_plane_axes(i)):
                        if len(labels & ser.index):
                            ser = ser.reindex(labels)
                        else:
                            broadcast.append((n, len(labels)))
                    ser = ser._values.copy()
                    for axis, l in broadcast:
                        shape = [-1] * (len(broadcast) + 1)
                        shape[axis] = l
                        ser = np.tile(ser, l).reshape(shape)
                    if self.obj.ndim == 3:
                        ser = ser.T
                    return ser
        elif is_scalar(indexer):
            ax = self.obj._get_axis(1)
            if ser.index.equals(ax):
                return ser._values.copy()
            return ser.reindex(ax)._values
        raise ValueError('Incompatible indexer with Series')

    def _align_frame(self, indexer, df):
        is_frame = self.obj.ndim == 2
        is_panel = self.obj.ndim >= 3
        if isinstance(indexer, tuple):
            idx, cols = None, None
            sindexers = []
            for i, ix in enumerate(indexer):
                ax = self.obj.axes[i]
                if is_sequence(ix) or isinstance(ix, slice):
                    if isinstance(ix, np.ndarray):
                        ix = ix.ravel()
                    if idx is None:
                        idx = ax[ix]
                    elif cols is None:
                        cols = ax[ix]
                    else:
                        break
                else:
                    sindexers.append(i)
            if is_panel:
                if len(sindexers) == 1 and sindexers[0] != 0:
                    df = df.T
                if idx is None:
                    idx = df.index
                if cols is None:
                    cols = df.columns
            if idx is not None and cols is not None:
                if df.index.equals(idx) and df.columns.equals(cols):
                    val = df.copy()._values
                else:
                    val = df.reindex(idx, columns=cols)._values
                return val
        elif (isinstance(indexer, slice) or is_list_like_indexer(indexer)
            ) and is_frame:
            ax = self.obj.index[indexer]
            if df.index.equals(ax):
                val = df.copy()._values
            else:
                if isinstance(ax, MultiIndex) and isinstance(df.index,
                    MultiIndex) and ax.nlevels != df.index.nlevels:
                    raise TypeError(
                        'cannot align on a multi-index with out specifying the join levels'
                        )
                val = df.reindex(index=ax)._values
            return val
        elif is_scalar(indexer) and is_panel:
            idx = self.obj.axes[1]
            cols = self.obj.axes[2]
            if idx.equals(df.index) and cols.equals(df.columns):
                return df.copy()._values
            return df.reindex(idx, columns=cols)._values
        raise ValueError('Incompatible indexer with DataFrame')

    def _align_panel(self, indexer, df):
        raise NotImplementedError(
            'cannot set using an indexer with a Panel yet!')

    def _getitem_tuple(self, tup):
        try:
            return self._getitem_lowerdim(tup)
        except IndexingError:
            pass
        self._has_valid_tuple(tup)
        if self._multi_take_opportunity(tup):
            return self._multi_take(tup)
        retval = self.obj
        for i, key in enumerate(tup):
            if i >= self.obj.ndim:
                raise IndexingError('Too many indexers')
            if com.is_null_slice(key):
                continue
            retval = getattr(retval, self.name)._getitem_axis(key, axis=i)
        return retval

    def _multi_take_opportunity(self, tup):
        """
        Check whether there is the possibility to use ``_multi_take``.
        Currently the limit is that all axes being indexed must be indexed with
        list-likes.

        Parameters
        ----------
        tup : tuple
            Tuple of indexers, one per axis

        Returns
        -------
        boolean: Whether the current indexing can be passed through _multi_take
        """
        if not all(is_list_like_indexer(x) for x in tup):
            return False
        if any(com.is_bool_indexer(x) for x in tup):
            return False
        return True

    def _multi_take(self, tup):
        """
        Create the indexers for the passed tuple of keys, and execute the take
        operation. This allows the take operation to be executed all at once -
        rather than once for each dimension - improving efficiency.

        Parameters
        ----------
        tup : tuple
            Tuple of indexers, one per axis

        Returns
        -------
        values: same type as the object being indexed
        """
        o = self.obj
        d = {axis: self._get_listlike_indexer(key, axis) for key, axis in
            zip(tup, o._AXIS_ORDERS)}
        return o._reindex_with_indexers(d, copy=True, allow_dups=True)

    def _convert_for_reindex(self, key, axis=None):
        return key

    def _handle_lowerdim_multi_index_axis0(self, tup):
        try:
            return self._get_label(tup, axis=self.axis)
        except TypeError:
            pass
        except Exception as e1:
            if isinstance(tup[0], (slice, Index)):
                raise IndexingError('Handle elsewhere')
            ax0 = self.obj._get_axis(0)
            if not ax0.is_lexsorted_for_tuple(tup):
                raise e1
        return None

    def _getitem_lowerdim(self, tup):
        if self.axis is not None:
            axis = self.obj._get_axis_number(self.axis)
            return self._getitem_axis(tup, axis=axis)
        if self._is_nested_tuple_indexer(tup):
            return self._getitem_nested_tuple(tup)
        ax0 = self.obj._get_axis(0)
        if isinstance(ax0, MultiIndex) and self.name != 'iloc':
            result = self._handle_lowerdim_multi_index_axis0(tup)
            if result is not None:
                return result
        if len(tup) > self.obj.ndim:
            raise IndexingError('Too many indexers. handle elsewhere')
        for i, key in enumerate(tup):
            if is_label_like(key) or isinstance(key, tuple):
                section = self._getitem_axis(key, axis=i)
                if not is_list_like_indexer(section):
                    return section
                elif section.ndim == self.ndim:
                    new_key = tup[:i] + (_NS,) + tup[i + 1:]
                else:
                    new_key = tup[:i] + tup[i + 1:]
                    if isinstance(section, ABCDataFrame) and i > 0 and len(
                        new_key) == 2:
                        a, b = new_key
                        new_key = b, a
                    if len(new_key) == 1:
                        new_key, = new_key
                if com.is_null_slice(new_key):
                    return section
                return getattr(section, self.name)[new_key]
        raise IndexingError('not applicable')

    def _getitem_nested_tuple(self, tup):
        if len(tup) > self.ndim:
            result = self._handle_lowerdim_multi_index_axis0(tup)
            if result is not None:
                return result
            return self._getitem_axis(tup, axis=self.axis)
        obj = self.obj
        axis = 0
        for i, key in enumerate(tup):
            if com.is_null_slice(key):
                axis += 1
                continue
            current_ndim = obj.ndim
            obj = getattr(obj, self.name)._getitem_axis(key, axis=axis)
            axis += 1
            if is_scalar(obj) or not hasattr(obj, 'ndim'):
                break
            if obj.ndim < current_ndim:
                if i >= 1 and current_ndim == 3 and obj.ndim == 2:
                    obj = obj.T
                axis -= 1
        return obj

    def _getitem_axis(self, key, axis=None):
        if axis is None:
            axis = self.axis or 0
        if is_iterator(key):
            key = list(key)
        self._validate_key(key, axis)
        labels = self.obj._get_axis(axis)
        if isinstance(key, slice):
            return self._get_slice_axis(key, axis=axis)
        elif is_list_like_indexer(key) and not (isinstance(key, tuple) and
            isinstance(labels, MultiIndex)):
            if hasattr(key, 'ndim') and key.ndim > 1:
                raise ValueError('Cannot index with multidimensional key')
            return self._getitem_iterable(key, axis=axis)
        else:
            key = labels._maybe_cast_indexer(key)
            if is_integer(key):
                if axis == 0 and isinstance(labels, MultiIndex):
                    try:
                        return self._get_label(key, axis=axis)
                    except (KeyError, TypeError):
                        if self.obj.index.levels[0].is_integer():
                            raise
                if not labels.is_floating() and not labels.is_integer():
                    return self._get_loc(key, axis=axis)
            return self._get_label(key, axis=axis)

    def _get_listlike_indexer(self, key, axis, raise_missing=False):
        """
        Transform a list-like of keys into a new index and an indexer.

        Parameters
        ----------
        key : list-like
            Target labels
        axis: int
            Dimension on which the indexing is being made
        raise_missing: bool
            Whether to raise a KeyError if some labels are not found. Will be
            removed in the future, and then this method will always behave as
            if raise_missing=True.

        Raises
        ------
        KeyError
            If at least one key was requested but none was found, and
            raise_missing=True.

        Returns
        -------
        keyarr: Index
            New index (coinciding with 'key' if the axis is unique)
        values : array-like
            An indexer for the return object; -1 denotes keys not found
        """
        o = self.obj
        ax = o._get_axis(axis)
        indexer, keyarr = ax._convert_listlike_indexer(key, kind=self.name)
        if indexer is not None and (indexer != -1).all():
            self._validate_read_indexer(key, indexer, axis, raise_missing=
                raise_missing)
            return ax[indexer], indexer
        if ax.is_unique:
            if len(ax) or not len(key):
                key = self._convert_for_reindex(key, axis)
            indexer = ax.get_indexer_for(key)
            keyarr = ax.reindex(keyarr)[0]
        else:
            keyarr, indexer, new_indexer = ax._reindex_non_unique(keyarr)
        self._validate_read_indexer(keyarr, indexer, o._get_axis_number(
            axis), raise_missing=raise_missing)
        return keyarr, indexer

    def _getitem_iterable(self, key, axis=None):
        """
        Index current object with an an iterable key (which can be a boolean
        indexer, or a collection of keys).

        Parameters
        ----------
        key : iterable
            Target labels, or boolean indexer
        axis: int, default None
            Dimension on which the indexing is being made

        Raises
        ------
        KeyError
            If no key was found. Will change in the future to raise if not all
            keys were found.
        IndexingError
            If the boolean indexer is unalignable with the object being
            indexed.

        Returns
        -------
        scalar, DataFrame, or Series: indexed value(s),
        """
        if axis is None:
            axis = self.axis or 0
        self._validate_key(key, axis)
        labels = self.obj._get_axis(axis)
        if com.is_bool_indexer(key):
            key = check_bool_indexer(labels, key)
            inds, = key.nonzero()
            return self.obj._take(inds, axis=axis)
        else:
            keyarr, indexer = self._get_listlike_indexer(key, axis,
                raise_missing=False)
            return self.obj._reindex_with_indexers({axis: [keyarr, indexer]
                }, copy=True, allow_dups=True)

    def _validate_read_indexer(self, key, indexer, axis, raise_missing=False):
        """
        Check that indexer can be used to return a result (e.g. at least one
        element was found, unless the list of keys was actually empty).

        Parameters
        ----------
        key : list-like
            Target labels (only used to show correct error message)
        indexer: array-like of booleans
            Indices corresponding to the key (with -1 indicating not found)
        axis: int
            Dimension on which the indexing is being made
        raise_missing: bool
            Whether to raise a KeyError if some labels are not found. Will be
            removed in the future, and then this method will always behave as
            if raise_missing=True.

        Raises
        ------
        KeyError
            If at least one key was requested but none was found, and
            raise_missing=True.
        """
        ax = self.obj._get_axis(axis)
        if len(key) == 0:
            return
        missing = (indexer < 0).sum()
        if missing:
            if missing == len(indexer):
                raise KeyError('None of [{key}] are in the [{axis}]'.format
                    (key=key, axis=self.obj._get_axis_name(axis)))
            if not (self.name == 'loc' and not raise_missing):
                not_found = list(set(key) - set(ax))
                raise KeyError('{} not in index'.format(not_found))
            _missing_key_warning = textwrap.dedent(
                """
            Passing list-likes to .loc or [] with any missing label will raise
            KeyError in the future, you can use .reindex() as an alternative.

            See the documentation here:
            https://pandas.pydata.org/pandas-docs/stable/indexing.html#deprecate-loc-reindex-listlike"""
                )
            if not (ax.is_categorical() or ax.is_interval()):
                warnings.warn(_missing_key_warning, FutureWarning, stacklevel=6
                    )

    def _convert_to_indexer(self, obj, axis=None, is_setter=False,
        raise_missing=False):
        """
        Convert indexing key into something we can use to do actual fancy
        indexing on an ndarray

        Examples
        ix[:5] -> slice(0, 5)
        ix[[1,2,3]] -> [1,2,3]
        ix[['foo', 'bar', 'baz']] -> [i, j, k] (indices of foo, bar, baz)

        Going by Zen of Python?
        'In the face of ambiguity, refuse the temptation to guess.'
        raise AmbiguousIndexError with integer labels?
        - No, prefer label-based indexing
        """
        if axis is None:
            axis = self.axis or 0
        labels = self.obj._get_axis(axis)
        if isinstance(obj, slice):
            return self._convert_slice_indexer(obj, axis)
        try:
            obj = self._convert_scalar_indexer(obj, axis)
        except TypeError:
            if is_setter:
                pass
        is_int_index = labels.is_integer()
        is_int_positional = is_integer(obj) and not is_int_index
        try:
            return labels.get_loc(obj)
        except LookupError:
            if isinstance(obj, tuple) and isinstance(labels, MultiIndex):
                if is_setter and len(obj) == labels.nlevels:
                    return {'key': obj}
                raise
        except TypeError:
            pass
        except ValueError:
            if not is_int_positional:
                raise
        if is_int_positional:
            if is_setter:
                if self.name == 'loc':
                    return {'key': obj}
                if obj >= self.obj.shape[axis] and not isinstance(labels,
                    MultiIndex):
                    raise ValueError(
                        'cannot set by positional indexing with enlargement')
            return obj
        if is_nested_tuple(obj, labels):
            return labels.get_locs(obj)
        elif is_list_like_indexer(obj):
            if com.is_bool_indexer(obj):
                obj = check_bool_indexer(labels, obj)
                inds, = obj.nonzero()
                return inds
            else:
                kwargs = {'raise_missing': True if is_setter else raise_missing
                    }
                return self._get_listlike_indexer(obj, axis, **kwargs)[1]
        else:
            try:
                return labels.get_loc(obj)
            except LookupError:
                if not is_list_like_indexer(obj) and is_setter:
                    return {'key': obj}
                raise

    def _tuplify(self, loc):
        tup = [slice(None, None) for _ in range(self.ndim)]
        tup[0] = loc
        return tuple(tup)

    def _get_slice_axis(self, slice_obj, axis=None):
        obj = self.obj
        if axis is None:
            axis = self.axis or 0
        if not need_slice(slice_obj):
            return obj.copy(deep=False)
        indexer = self._convert_slice_indexer(slice_obj, axis)
        if isinstance(indexer, slice):
            return self._slice(indexer, axis=axis, kind='iloc')
        else:
            return self.obj._take(indexer, axis=axis)

