        __call__ = 5

        def __repr__(self):
            return 'NotCallable()'


    class Foo:
        foo = NotCallable()
    foo = Foo()
    assert callable(foo.foo)
    expected = """╭─ <class 'tests.test_inspect.test_broken_call_attr.<locals>.Foo'> ─╮
│ foo = NotCallable()                                               │
╰───────────────────────────────────────────────────────────────────╯
"""
    result = render(foo, methods=True, width=100)
    print(repr(result))
    assert expected == result

